def block_centers(A):
    import numpy as np
    A=np.array(A); H,W=A.shape
    seen=A.copy()
    regs=[]
    for i in range(H):
        for j in range(W):
            if A[i,j]!=0 and A[i,j]!=4 and seen[i,j]:
                col=A[i,j]; stack=[(i,j)]; cells=[]
                seen[i,j]=0
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and seen[ny,nx] and A[ny,nx]==col:
                            seen[ny,nx]=0; stack.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                regs.append((col,(sum(ys)//len(ys), sum(xs)//len(xs))))
    return regs

def f(G):
    import numpy as np
    A=np.array(G).copy(); H,W=A.shape
    regs=block_centers(G)
    byc={}
    for col,c in regs: byc.setdefault(col,[]).append(c)
    def is_gap(y,x): return A[y,x]==0
    for col,pts in byc.items():
        if len(pts)!=4: continue
        rs=sorted({p[0] for p in pts}); cs=sorted({p[1] for p in pts})
        if len(rs)!=2 or len(cs)!=2: continue
        if set(pts)!={(rs[0],cs[0]),(rs[0],cs[1]),(rs[1],cs[0]),(rs[1],cs[1])}: continue
        # fill gaps along rectangle edges
        for r in rs:
            for x in range(min(cs),max(cs)+1):
                if is_gap(r,x): A[r,x]=col
        for c in cs:
            for y in range(min(rs),max(rs)+1):
                if is_gap(y,c): A[y,c]=col
    return A.tolist()

